[{"id":"BoKRw5LNb3Vb2NadUJRU","begin":"2026-09-25T15:47:00+00:00","created":"2026-09-25T16:29:32+00:00","end":"2026-09-25T16:40:00+00:00","modified":"2026-09-25T16:53:22+00:00","external_desc":"**Summary:**\nMitigating elevated error rate with Google Workspace Studio web.\n**Description:**\nMitigation work is currently underway by our engineering team.\nWe do not have an ETA for mitigation at this point.\nWe will provide more information by Friday, 2026-09-25 10:30 PDT.\n**Symptoms:**\nCustomers may experience an endless loading screen when attempting to access Google Workspace Studio on the web.\n**Workaround:**\nNone at this time.","most_recent_update":{"created":"2026-09-25T16:52:54+00:00","modified":"2026-09-25T16:53:22+00:00","when":"2026-09-25T16:52:54+00:00","text":"**Summary:**\nMitigated elevated error rate with Google Workspace Studio web.\n**Description:**\nThe issue with Google Workspace Studio has been resolved for all affected users as of Friday, 2026-09-25 09:40 PDT.\nFrom preliminary analysis, the root cause of the issue is a recent rollout. Our engineering team has rolled back which mitigated the issue.\nWe thank you for your patience while we worked on resolving the issue.\n**Symptoms:**\nCustomers may have experienced an endless loading screen when attempting to access Google Workspace Studio on the web.\n**Workaround:**\nThe issue is now mitigated.","status":"AVAILABLE"},"status_impact":"SERVICE_INFORMATION","severity":"low","service_key":"m5tLdjJLc4EL8ZTnL5RZ","service_name":"Google Workspace Studio","affected_products":[{"title":"Google Workspace Studio","id":"m5tLdjJLc4EL8ZTnL5RZ"}],"uri":"incidents/BoKRw5LNb3Vb2NadUJRU"},{"id":"B5V4MfnVp97nxoTYbxdX","begin":"2026-09-18T05:00:00+00:00","created":"2026-09-22T21:38:51+00:00","end":"2026-09-24T18:00:00+00:00","modified":"2026-09-25T00:04:37+00:00","external_desc":"**Title:**\nGmail Android App users on the latest Gmail Android release may experience issues accessing their inbox.\n**Description:**\nOur engineering team has identified the root cause and is actively working on mitigating the issue.\nWe will provide more information by Tuesday, 2026-09-22 18:00 PDT.\n**Symptoms:**\n- Users on the Gmail Android app are finding that their accounts unexpectedly appear logged out.\n- Upon re-login, the process completes but the app fails to recognize the account.\n- Users receive an error message stating the account is already added.\n**Workaround:**\nThe workaround for the Gmail app issue is to uninstall recent application updates and revert to the system's base version of Gmail. Optionally reinstall the latest version of the Gmail app from play store.\nAlternatively, users can access https://mail.google.com on their mobile browsers.","most_recent_update":{"created":"2026-09-25T00:04:24+00:00","modified":"2026-09-25T00:04:37+00:00","when":"2026-09-25T00:04:24+00:00","text":"**summary**\nGmail Android App users on the previous Gmail Android release may have experienced issues accessing their inbox.\n**Description**\nThe issue with Gmail Android App has been resolved for all affected users as of Thursday, 2026-09-24 11:00 PDT.\nWe thank you for your patience while we worked on resolving the issue.\n**Symptoms**\nUsers on the Gmail Android app may observe sudden, unexpected account logout.\nUpon re-login, the process completes but the app may fail to recognize the account.\nUsers may receive an error message stating the account is already added.\n**Workaround**\nA fix has been rolled out with the latest version of the Gmail Android app. Users can update to the latest version within the Play Store to resolve this issue.","status":"AVAILABLE"},"status_impact":"SERVICE_INFORMATION","severity":"low","service_key":"prPt2Yra2CbGsbEm9cpC","service_name":"Gmail","affected_products":[{"title":"Gmail","id":"prPt2Yra2CbGsbEm9cpC"}],"uri":"incidents/B5V4MfnVp97nxoTYbxdX"},{"id":"Xck6rcpnzZ4pSTAY2MVa","begin":"2025-12-01T08:00:00+00:00","created":"2025-12-02T04:20:49+00:00","end":null,"modified":"2025-12-04T21:28:52+00:00","external_desc":"**Summary**\nSome Google Meet customers may experience an issue with ‘Continuous meeting chat’ feature\n**Description**\nGoogle Workspace released a feature to a subset of Workspace customers [Continue your conversations in Google Chat](https://support.google.com/meet/answer/9308979?visit_id=639002449653293387-821172296&p=chat_in_meet&rd=1).\nSome Google Workspace users are experiencing issues with Google Meet host controls for this feature. This may include inability to disable the feature or the ‘disable’ option not being visible under the host controls within Google Calendar meeting invites.\nWe are investigating and will provide an update by Friday, 2025-12-05 10:00 PST with current details.\nWe apologize to all who are affected by this issue.\n**Symptoms**\nThe impacted users are unable to observe Chat moderation settings under the Host Controls for ‘Continuous meeting chat’ feature.\n**Workaround**\nNone at this time.","most_recent_update":{"created":"2025-12-04T21:28:49+00:00","modified":"2025-12-04T21:28:52+00:00","when":"2025-12-04T21:28:49+00:00","text":"**Summary**\nSome Google Meet customers may experience an issue with ‘Continuous meeting chat’ feature\n**Description**\nThe rollback of the \"Continue your conversations in Google Chat\" feature in Google Meet is now complete. This resolves the issues some users experienced, including the inability to disable the feature and the missing toggle in Calendar host controls.\nWe will commence the rollout of this feature again starting Monday, 2025-12-08. No further updates will be provided here. For more detailed information regarding the updated rollout schedule, please refer to the [Google Workspace Updates Blog](https://workspaceupdates.googleblog.com/2025/11/continue-conversations-google-chat-google-meet.html).\nWe apologize for the disruption this may have caused.\n**Symptoms**\nThe impacted users are unable to observe Chat moderation settings under the Host Controls for ‘Continuous meeting chat’ feature.\n**Workaround**\nNone at this time.","status":"AVAILABLE"},"status_impact":"SERVICE_INFORMATION","severity":"low","service_key":"sUH4BQXzYXma7NiS94Hi","service_name":"Google Meet","affected_products":[{"title":"Google Meet","id":"sUH4BQXzYXma7NiS94Hi"}],"uri":"incidents/Xck6rcpnzZ4pSTAY2MVa"}]
